INSERT INTO `site_intro` (`id`, `content`) VALUES
(1, '<p>Đoàn Thanh niên - Hội Sinh viên Khoa Điện tử, Trường Đại học Kỹ thuật Công nghiệp (TNUT) là tổ chức chính trị - xã hội của sinh viên trong khoa, đóng vai trò quan trọng trong việc giáo dục lý tưởng, đạo đức, lối sống và phát huy tinh thần xung kích, sáng tạo của sinh viên.</p>\n<p>Trong nhiều năm qua, Đoàn - Hội FEE đã tổ chức nhiều hoạt động ý nghĩa như: tình nguyện vì cộng đồng, hiến máu nhân đạo, mùa hè xanh, các cuộc thi học thuật, hoạt động văn hóa - văn nghệ - thể thao, góp phần xây dựng môi trường học tập năng động và sáng tạo cho sinh viên.</p>');
