INSERT INTO `truyen_thong` (`MaBaiViet`, `TieuDe`, `NoiDung`, `NgayDang`, `link_bai_viet`) VALUES
(1, 'Tuyên dương sinh viên tiêu biểu', 'Danh hiệu \"Thanh niên tiên tiến làm theo lời Bác cấp Đại học Thái Nguyên\" là một dấu mốc rực rỡ, một phần thưởng vô cùng xứng đáng cho những nỗ lực bền bỉ, tinh thần cống hiến không mệt mỏi và phẩm chất đạo đức sáng ngời của đồng chí trong suốt thời gian qua.\r\n💫Hành trình đi đến danh hiệu cao quý này chắc chắn không trải đầy hoa hồng. Để cân bằng giữa những áp lực học tập khắt khe của ngành Kỹ thuật Máy tính và khối lượng công việc đồ sộ của một cán bộ cốt cán trong Đoàn Thanh niên - Hội Sinh viên khoa Điện tử, đồng chí đã phải đánh đổi bằng rất nhiều mồ hôi, tâm huyết và cả những đêm thức trắng. Ngọn lửa nhiệt huyết của đồng chí đã góp phần không nhỏ vào sự vững mạnh của phong trào sinh viên, truyền cảm hứng mạnh mẽ đến thế hệ trẻ và những người đồng chí, đồng đội xung quanh.\r\n❤️‍🔥Nhân dịp đặc biệt này, xin gửi tới đồng chí những lời chúc tốt đẹp nhất. Chúc đồng chí luôn giữ vững trái tim rực cháy nhiệt huyết của tuổi trẻ, tiếp tục là lá cờ đầu trong các phong trào của Khoa và Nhà trường. Mong rằng danh hiệu cao quý này sẽ không phải là đích đến, mà là bệ phóng vững chắc để đồng chí vươn xa hơn nữa. Chúc đồng chí luôn giữ bản lĩnh kiên cường, tư duy nhạy bén và trái tim ấm áp để lan tỏa những điều tốt đẹp.\r\n🤩 Một lần nữa, xin nhiệt liệt chúc mừng đồng chí Chu Đặng Trung Long. Chúc đồng chí sức khỏe, hạnh phúc và không ngừng tiến bước, mãi là niềm tự hào của tuổi trẻ khoa Điện tử!', '2026-05-28 00:00:00', 'https://www.facebook.com/share/p/14aWBQKW8Uv/');
